117	  state: AgentState,
118	  proposal: CandidateProposal,
119	  result: ToolResult,
120	  modified: string[],
121	  refreshFailed: boolean,
122	): AgentEvidence {
123	  const previous = currentEvidence(state);
124	  let evidence: AgentEvidence = { ...previous };
125	  if (!result.ok) {
126	    evidence.failures = [...previous.failures, {
127	      iteration: state.iteration,
128	      action: proposal.action,
129	      summary: truncateText(result.output, 1_000),
130	    }].slice(-8);
131	  }
132	  if (proposal.action === 'SEARCH_REPO' && result.ok) {
133	    const finding = { iteration: state.iteration, source: 'search' as const, paths: result.files.slice(0, 8) };
134	    if (!previous.findings.some((item) => item.source === finding.source &&
135	      JSON.stringify(item.paths) === JSON.stringify(finding.paths))) {
136	      evidence = {
137	        ...evidence,
138	        revision: evidence.revision + 1,
139	        lastRevisionSource: 'search',
140	        findings: [...previous.findings, finding].slice(-8),
141	      };
142	    }
143	  }
144	  if (proposal.action === 'READ_FILE' && result.ok) {
145	    const finding = {
146	      iteration: state.iteration,
147	      source: 'read' as const,
148	      paths: result.files.slice(0, 8),
149	      excerpt: truncateText(result.output, 1_000),
150	    };
151	    if (!previous.findings.some((item) => item.source === finding.source &&
152	      JSON.stringify(item.paths) === JSON.stringify(finding.paths) && item.excerpt === finding.excerpt)) {
153	      evidence = {
154	        ...evidence,
