205	function canUserOverrideFinish(
206	  state: AgentState,
207	  evaluation: EvaluationResult,
208	  policy: PolicyDecision,
209	): boolean {
210	  if (
211	    state.repo.validationScripts.length === 0 ||
212	    state.tests.ran !== true ||
213	    state.tests.passed !== true ||
214	    policy.requested !== 'FINISH' ||
215	    policy.selected !== 'ASK_USER' ||
216	    evaluation.assessment.needsMoreInformation.probability >= DEFAULT_THRESHOLDS.askUser ||
217	    evaluation.assessment.stuck.probability >= DEFAULT_THRESHOLDS.askUser
218	  ) {
219	    return false;
220	  }
221	
222	  const finishProbability = evaluation.assessment.nextAction.probabilities.FINISH ?? 0;
223	  const confidence = evaluation.assessment.nextAction.confidence ?? 0;
224	  return finishProbability >= DEFAULT_THRESHOLDS.minChoiceProbability &&
225	    confidence >= DEFAULT_THRESHOLDS.minChoiceConfidence;
226	}
