305	async function safelyExecute(
306	  proposal: Exclude<CandidateProposal, { action: 'ASK_USER' | 'FINISH' }>,
307	  execute: typeof executeCandidate,
308	): Promise<ToolResult> {
309	  const startedAt = performance.now();
310	  try {
311	    const result: unknown = await execute(proposal);
312	    if (!isToolResult(result, proposal.action)) {
313	      throw new Error('The tool executor returned a malformed result.');
314	    }
315	    return result;
316	  } catch (error) {
317	    return {
318	      action: proposal.action,
319	      ok: false,
320	      exitCode: null,
321	      durationMs: Math.round(performance.now() - startedAt),
322	      timedOut: false,
323	      output: truncateText(
