332	function applyToolResult(
333	  state: AgentState,
334	  proposal: CandidateProposal,
335	  result: ToolResult,
336	  refreshedRepo?: RepoSnapshot,
337	  refreshFailed: boolean = false,
338	): AgentState {
339	  const signature = proposalSignature(proposal, state);
340	  const observations = [...state.observations];
341	  const failedApproaches = [...state.failedApproaches];
342	  let filesRead = state.filesRead;
343	  let filesModified = state.filesModified;
344	  let commandsRun = state.commandsRun;
345	  let tests = state.tests;
346	  let currentGoal = state.currentGoal;
347	  let repo = state.repo;
348	  let codexCalls = state.codexCalls;
349	  let claudeCalls = state.claudeCalls;
350	
351	  if (!result.ok) {
352	    failedApproaches.push(signature);
353	    observations.push(`${proposal.action} failed: ${truncateText(result.output, MAX_OBSERVATION_LENGTH)}`);
354	    currentGoal = 'Gather information before retrying a failed approach.';
355	  } else if (proposal.action === 'SEARCH_REPO') {
356	    const summary = result.files.length > 0 ? result.files.join(', ') : 'no matching files';
357	    observations.push(`Search completed: ${truncateText(summary, MAX_OBSERVATION_LENGTH)}`);
358	    currentGoal = 'Inspect a safe repository file informed by the search.';
359	  } else if (proposal.action === 'READ_FILE') {
360	    filesRead = [...new Set([...state.filesRead, ...result.files])];
361	    observations.push(`Read ${result.files[0] ?? proposal.input.path}: ${truncateText(result.output, MAX_OBSERVATION_LENGTH)}`);
362	    currentGoal = 'Validate the repository after inspection.';
363	  } else if (proposal.action === 'RUN_COMMAND') {
364	    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
365	    observations.push(`Diagnostic completed: ${summary}`);
366	    currentGoal = 'Use the approved diagnostic result to choose the next action.';
367	  } else if (proposal.action === 'RUN_TESTS') {
368	    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
369	    commandsRun = [...state.commandsRun, {
370	      command: commandDescription(proposal),
371	      exitCode: result.exitCode ?? 1,
372	      output: summary,
373	    }];
374	    tests = { ran: true, passed: true, summary };
375	    observations.push(`Validation passed: ${summary}`);
376	    currentGoal = 'Determine whether the requested task is complete.';
377	  } else if (isCodingAgentProposal(proposal)) {
378	    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
379	    commandsRun = [...state.commandsRun, {
380	      command: codingAgentCommand(proposal),
381	      exitCode: result.exitCode ?? 1,
382	      output: summary,
383	    }];
384	    observations.push(`${codingAgentName(proposal)} completed: ${summary}`);
385	    tests = { ran: false };
386	    currentGoal = `Validate the ${codingAgentName(proposal)} changes with an approved repository script.`;
387	  }
388	
389	  if (proposal.action === 'RUN_TESTS' && !result.ok) {
390	    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
391	    commandsRun = [...state.commandsRun, {
392	      command: commandDescription(proposal),
393	      exitCode: result.exitCode ?? 1,
394	      output: summary,
395	    }];
396	    tests = { ran: true, passed: false, summary };
397	  }
398	
399	  if (proposal.action === 'RUN_COMMAND') {
400	    const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
401	    commandsRun = [...state.commandsRun, {
402	      command: commandDescription(proposal),
403	      exitCode: result.exitCode ?? 1,
404	      output: summary,
405	    }];
406	  }
407	
408	  if (isCodingAgentProposal(proposal)) {
409	    if (proposal.action === 'CALL_CODEX') codexCalls += 1;
410	    else claudeCalls += 1;
411	    if (!result.ok) {
412	      const summary = truncateText(result.output, MAX_OBSERVATION_LENGTH);
413	      commandsRun = [...state.commandsRun, {
414	        command: codingAgentCommand(proposal),
415	        exitCode: result.exitCode ?? 1,
416	        output: summary,
417	      }];
418	    }
419	    if (refreshedRepo !== undefined) {
420	      repo = refreshedRepo;
421	      filesModified = modifiedFiles(refreshedRepo);
422	    }
423	    tests = { ran: false };
424	  }
425	
426	  return {
427	    ...state,
428	    repo,
429	    currentGoal,
430	    filesRead,
431	    filesModified,
432	    observations,
433	    commandsRun,
434	    tests,
435	    failedApproaches,
436	    codexCalls,
437	    claudeCalls,
438	    evidence: withToolEvidence(state, proposal, result, filesModified, refreshFailed),
439	  };
440	}
