279	function isToolResult(value: unknown, action: CandidateProposal['action']): value is ToolResult {
280	  if (value === null || typeof value !== 'object') return false;
281	  const result = value as Partial<ToolResult>;
282	  return result.action === action &&
283	    typeof result.ok === 'boolean' &&
284	    (result.exitCode === null || Number.isInteger(result.exitCode)) &&
285	    (!result.ok || (result.exitCode === 0 || (action === 'SEARCH_REPO' && result.exitCode === 1))) &&
286	    (!result.timedOut || !result.ok) &&
287	    typeof result.durationMs === 'number' &&
288	    Number.isFinite(result.durationMs) &&
289	    result.durationMs >= 0 &&
290	    typeof result.timedOut === 'boolean' &&
291	    typeof result.output === 'string' &&
292	    Array.isArray(result.files) &&
293	    result.files.every((file) => typeof file === 'string') &&
294	    (result.stdout === undefined || typeof result.stdout === 'string') &&
295	    (result.stderr === undefined || typeof result.stderr === 'string');
