  1	import { spawn } from 'node:child_process';
  2	
  3	export const MAX_PROCESS_OUTPUT_BYTES = 16 * 1024;
  4	export const FORCE_KILL_GRACE_MS = 1_000;
  5	
  6	export type ProcessRequest = {
  7	  command: string;
  8	  args: string[];
  9	  cwd: string;
 10	  timeoutMs: number;
 11	};
 12	
 13	export type ProcessResult = {
 14	  exitCode: number | null;
 15	  stdout: string;
 16	  stderr: string;
 17	  timedOut: boolean;
 18	};
 19	
 20	export type ProcessRunner = (request: ProcessRequest) => Promise<ProcessResult>;
 21	
 22	export class ProcessExecutionError extends Error {
 23	  constructor(message: string) {
 24	    super(message);
 25	    this.name = 'ProcessExecutionError';
 26	  }
 27	}
 28	
 29	function appendBounded(current: Buffer[], chunk: Buffer, byteCount: { value: number }): void {
 30	  const available = MAX_PROCESS_OUTPUT_BYTES - byteCount.value;
 31	  if (available <= 0) return;
 32	  const bounded = chunk.subarray(0, available);
 33	  current.push(bounded);
 34	  byteCount.value += bounded.length;
 35	}
 36	
 37	export const runProcess: ProcessRunner = async (request) => new Promise((resolve, reject) => {
 38	  const useProcessGroup = process.platform !== 'win32';
 39	  const child = spawn(request.command, request.args, {
 40	    cwd: request.cwd,
 41	    env: process.env,
 42	    detached: useProcessGroup,
 43	    shell: false,
 44	    stdio: ['ignore', 'pipe', 'pipe'],
 45	  });
 46	  const stdout: Buffer[] = [];
 47	  const stderr: Buffer[] = [];
 48	  const stdoutBytes = { value: 0 };
 49	  const stderrBytes = { value: 0 };
 50	  let timedOut = false;
 51	  let settled = false;
 52	  let forceKillTimeout: NodeJS.Timeout | undefined;
 53	  const kill = (signal: NodeJS.Signals): void => {
 54	    try {
 55	      if (useProcessGroup && child.pid !== undefined) {
 56	        process.kill(-child.pid, signal);
 57	      } else {
 58	        child.kill(signal);
 59	      }
 60	    } catch {
 61	      child.kill(signal);
 62	    }
 63	  };
 64	  const timeout = setTimeout(() => {
 65	    timedOut = true;
 66	    kill('SIGTERM');
 67	    forceKillTimeout = setTimeout(() => kill('SIGKILL'), FORCE_KILL_GRACE_MS);
 68	    forceKillTimeout.unref();
 69	  }, request.timeoutMs);
 70	  timeout.unref();
 71	
 72	  child.stdout.on('data', (chunk: Buffer) => appendBounded(stdout, chunk, stdoutBytes));
 73	  child.stderr.on('data', (chunk: Buffer) => appendBounded(stderr, chunk, stderrBytes));
 74	  child.on('error', (error) => {
 75	    if (settled) return;
 76	    settled = true;
 77	    clearTimeout(timeout);
 78	    if (forceKillTimeout !== undefined) clearTimeout(forceKillTimeout);
 79	    reject(new ProcessExecutionError(`Unable to start ${request.command}: ${error.message}`));
 80	  });
 81	  child.on('close', (exitCode) => {
 82	    if (settled) return;
 83	    settled = true;
 84	    clearTimeout(timeout);
 85	    if (forceKillTimeout !== undefined) clearTimeout(forceKillTimeout);
 86	    resolve({
 87	      exitCode,
 88	      stdout: Buffer.concat(stdout).toString('utf8'),
 89	      stderr: Buffer.concat(stderr).toString('utf8'),
 90	      timedOut,
 91	    });
 92	  });
 93	});
 94	
 95	export function validateProcessResult(result: ProcessResult): void {
 96	  if (
 97	    (result.exitCode !== null && !Number.isInteger(result.exitCode)) ||
 98	    typeof result.stdout !== 'string' ||
 99	    typeof result.stderr !== 'string' ||
100	    typeof result.timedOut !== 'boolean'
101	  ) {
102	    throw new ProcessExecutionError('The process runner returned a malformed result.');
103	  }
104	}
  1	import {
  2	  runProcess,
  3	  validateProcessResult,
  4	  type ProcessRunner,
