513	export async function runOrchestration(
514	  initialState: AgentState,
515	  dependencies: OrchestrationDependencies,
516	  options: OrchestrationOptions = {},
517	): Promise<OrchestrationResult> {
518	  const maxIterations = options.maxIterations ?? MAX_ORCHESTRATION_ITERATIONS;
519	  if (!Number.isInteger(maxIterations) || maxIterations < 1 || maxIterations > MAX_ORCHESTRATION_ITERATIONS) {
520	    throw new Error(`Iteration limit must be between 1 and ${MAX_ORCHESTRATION_ITERATIONS}.`);
521	  }
522	
523	  const trace = await createOrchestrationTrace(initialState.repo.root);
524	  const execute = dependencies.execute ?? executeCandidate;
525	  const inspect = dependencies.inspect ?? inspectRepo;
526	  let state = initialState;
527	  let searchResults: string[] = [];
528	
529	  for (let iteration = 1; iteration <= maxIterations; iteration += 1) {
530	    state = { ...state, iteration };
531	    const stateBefore = state;
532	    const evaluation = await dependencies.evaluate(state);
533	    const policy = applyPolicy(state, evaluation.assessment);
534	    const selected = repeatedFailureProposal(
535	      await selectCandidate(policy.selected, state, searchResults),
536	      state,
537	    );
538	    const approval = await resolveApproval(
539	      selected,
540	      state,
541	      evaluation,
542	      policy,
543	      dependencies.approve,
544	      searchResults,
545	    );
546	    const { proposal } = approval;
547	    let { decision } = approval;
548	    if (decision.kind === 'approve') {
549	      const blockedRepeat = state.failedApproaches.includes(proposalSignature(proposal, state));
550	      const exhaustedCodex = proposal.action === 'CALL_CODEX' && state.codexCalls >= MAX_CODEX_CALLS;
551	      const exhaustedClaude = proposal.action === 'CALL_CLAUDE' && state.claudeCalls >= MAX_CLAUDE_CALLS;
552	      if (blockedRepeat || exhaustedCodex || exhaustedClaude ||
553	        (state.evidence?.repoRefreshRequired && proposal.action !== 'ASK_USER')) {
554	        decision = {
555	          kind: 'reject',
556	          reason: blockedRepeat
557	            ? 'The resolved candidate already failed with the same relevant evidence.'
558	            : 'Repository inspection or a worker call limit prevents execution.',
559	        };
560	        approval.decisions.push(decision);
561	      }
562	    }
563	    let toolResult: ToolResult | null = null;
564	    let nextState = state;
565	    let terminalStatus: Extract<OrchestrationStatus, 'finished' | 'stopped'> | undefined;
566	
567	    if (decision.kind === 'stop') {
568	      terminalStatus = 'stopped';
569	      nextState = {
570	        ...state,
571	        observations: [...state.observations, stopObservation(decision)],
572	        currentGoal: 'Run stopped by user without claiming completion.',
573	      };
574	    } else if (decision.kind === 'reject') {
575	      nextState = {
576	        ...state,
577	        observations: [...state.observations, rejectionObservation(decision)],
578	        currentGoal: 'Choose a permitted alternative after user rejection.',
579	      };
580	    } else if (proposal.action === 'ASK_USER') {
581	      const information = truncateText(
582	        (await dependencies.askForInformation(state)).trim(),
583	        MAX_OBSERVATION_LENGTH,
584	      );
585	      nextState = withClarification({
586	        ...state,
587	        observations: [
588	          ...state.observations,
589	          information ? `User supplied information: ${information}` : 'User supplied no additional information.',
590	        ],
591	        currentGoal: 'Reassess the task with the user response.',
592	      }, information);
593	      // Recovery requires the approved user-input boundary as well as a fresh
594	      // snapshot. Rejection, stop, and alternative selection never reach here.
595	      if (nextState.evidence?.repoRefreshRequired) {
596	        try {
597	          const refreshed = await inspect(state.repo.root);
598	          const modified = modifiedFiles(refreshed);
599	          nextState = {
600	            ...nextState,
601	            repo: refreshed,
602	            filesModified: modified,
603	            evidence: {
604	              ...nextState.evidence,
605	              repoRefreshRequired: false,
606	              ...(nextState.evidence.worker ? {
607	                worker: { ...nextState.evidence.worker, modifiedFiles: modified.slice(0, 8) },
608	              } : {}),
609	            },
610	            observations: [...nextState.observations, 'Repository inspection recovered after user intervention.'],
611	          };
612	        } catch {
613	          nextState = {
614	            ...nextState,
615	            observations: [...nextState.observations, 'Repository inspection still requires recovery after user intervention.'],
616	          };
617	        }
618	      }
619	    } else if (proposal.action === 'FINISH') {
620	      terminalStatus = 'finished';
621	      const completionObservation = policy.selected === 'FINISH'
622	        ? 'User approved completion.'
623	        : 'User explicitly overrode completion confidence after passing validation.';
624	      nextState = {
625	        ...state,
626	        observations: [...state.observations, completionObservation],
627	        currentGoal: 'Task complete.',
628	      };
629	    } else {
630	      toolResult = await safelyExecute(proposal, execute);
631	      if (proposal.action === 'SEARCH_REPO' && toolResult.ok) searchResults = toolResult.files;
632	      let refreshedRepo: RepoSnapshot | undefined;
633	      let refreshFailed = false;
634	      if (isCodingAgentProposal(proposal)) {
635	        try {
636	          refreshedRepo = await inspect(state.repo.root);
637	        } catch {
638	          refreshFailed = true;
639	          toolResult = {
640	            ...toolResult,
641	            ok: false,
642	            output: `${toolResult.output}\nUnable to inspect the repository after ${codingAgentName(proposal)} execution.`,
643	          };
644	        }
645	      }
646	      nextState = applyToolResult(state, proposal, toolResult, refreshedRepo, refreshFailed);
647	    }
648	
649	    const reachedLimit = terminalStatus === undefined && iteration === maxIterations;
650	    if (reachedLimit) {
651	      nextState = {
652	        ...nextState,
653	        observations: [...nextState.observations, `Stopped at the ${maxIterations}-iteration limit.`],
654	        currentGoal: 'Ask the user how to continue after the iteration limit.',
655	      };
656	    }
657	
658	    await appendOrchestrationTrace(trace, {
659	      iteration,
660	      stateBefore,
661	      evaluation,
662	      policy,
663	      proposal: { considered: approval.proposals, selected: structuredClone(proposal) },
664	      approval: { ...decision, history: approval.decisions },
665	      toolInput: decision.kind === 'stop' ? null : proposal.input,
666	      toolResult,
667	      stateAfter: nextState,
668	      ...(isCodingAgentProposal(proposal) ? {
669	        workerRequest: {
670	          id: proposalSignature(proposal, state),
671	          evidenceRevision: state.evidence?.revision ?? 0,
672	          validationGeneration: state.evidence?.validationGeneration ?? 0,
673	          clarificationIterations: proposal.input.context.clarifications.map((item) => item.iteration),
674	          findingPaths: proposal.input.context.findings.flatMap((item) => item.paths).slice(0, 8),
675	          retryReason: decision.kind !== 'approve'
676	            ? 'Worker proposal was not executed.'
677	            : state.evidence?.validation?.passed === false
678	              ? 'Repair after failed independent validation.'
679	              : state.evidence?.worker?.ok === false
680	                ? state.evidence.worker.agent !== (proposal.action === 'CALL_CODEX' ? 'codex' : 'claude')
681	                  ? 'User selected another agent after a failed worker.'
682	                  : state.evidence.revision > state.evidence.worker.evidenceRevision
683	                    ? `New ${state.evidence.lastRevisionSource ?? 'repository'} evidence after a failed worker.`
684	                    : 'Approved worker request after prior failure.'
685	                : 'Approved worker request.',
686	        },
687	      } : {}),
688	    });
689	    state = nextState;
690	
691	    if (terminalStatus !== undefined) {
692	      return {
693	        status: terminalStatus,
694	        state,
695	        tracePath: trace.path,
696	        iterations: iteration,
697	      };
698	    }
699	  }
700	
701	  return {
702	    status: 'iteration_limit',
703	    state,
704	    tracePath: trace.path,
705	    iterations: maxIterations,
706	  };
707	}

