249	export function parseApprovalChoice(
250	  value: string,
251	  context: ApprovalContext,
252	): ApprovalDecision | undefined {
253	  const normalized = value.trim().toUpperCase();
254	  if (normalized === 'A' || normalized === 'APPROVE') return { kind: 'approve' };
255	  if (normalized === 'R' || normalized === 'REJECT') return { kind: 'reject' };
256	  if (normalized === 'STOP' || normalized === 'QUIT') return { kind: 'stop' };
257	
258	  const actionAliases: Partial<Record<string, ApprovalDecision>> = {
259	    SEARCH: { kind: 'alternative', action: 'SEARCH_REPO' },
260	    SEARCH_REPO: { kind: 'alternative', action: 'SEARCH_REPO' },
261	    READ: { kind: 'alternative', action: 'READ_FILE' },
262	    READ_FILE: { kind: 'alternative', action: 'READ_FILE' },
263	    COMMAND: { kind: 'alternative', action: 'RUN_COMMAND' },
264	    RUN_COMMAND: { kind: 'alternative', action: 'RUN_COMMAND' },
265	    TEST: { kind: 'alternative', action: 'RUN_TESTS' },
266	    RUN_TESTS: { kind: 'alternative', action: 'RUN_TESTS' },
267	    CODEX: { kind: 'alternative', action: 'CALL_CODEX' },
268	    CALL_CODEX: { kind: 'alternative', action: 'CALL_CODEX' },
269	    CLAUDE: { kind: 'alternative', action: 'CALL_CLAUDE' },
270	    CALL_CLAUDE: { kind: 'alternative', action: 'CALL_CLAUDE' },
271	    ASK: { kind: 'alternative', action: 'ASK_USER' },
272	    ASK_USER: { kind: 'alternative', action: 'ASK_USER' },
273	    FINISH: { kind: 'alternative', action: 'FINISH' },
274	  };
275	  const decision = actionAliases[normalized];
276	  if (decision?.kind === 'alternative' && context.allowedAlternatives.includes(decision.action)) {
277	    return decision;
278	  }
279	  return undefined;
280	}
