   503	function repeatedFailureProposal(proposal: CandidateProposal, state: AgentState): CandidateProposal {
   504	  if (!state.failedApproaches.includes(proposalSignature(proposal, state))) return proposal;
   505	  return {
   506	    action: 'ASK_USER',
   507	    tool: null,
   508	    input: null,
   509	    reason: 'The same resolved candidate already failed; policy requires new information.',
   510	  };
   511	}
