   513	export async function runOrchestration(
   514	  initialState: AgentState,
   515	  dependencies: OrchestrationDependencies,
   516	  options: OrchestrationOptions = {},
   517	): Promise<OrchestrationResult> {
   518	  const maxIterations = options.maxIterations ?? MAX_ORCHESTRATION_ITERATIONS;
   519	  if (!Number.isInteger(maxIterations) || maxIterations < 1 || maxIterations > MAX_ORCHESTRATION_ITERATIONS) {
   520	    throw new Error(`Iteration limit must be between 1 and ${MAX_ORCHESTRATION_ITERATIONS}.`);
   521	  }
   522	
   523	  const trace = await createOrchestrationTrace(initialState.repo.root);
   524	  const execute = dependencies.execute ?? executeCandidate;
   525	  const inspect = dependencies.inspect ?? inspectRepo;
   526	  let state = initialState;
   527	  let searchResults: string[] = [];
   528	
