 79	export function redactSensitiveText(
 80	  value: string,
 81	  secretValues: string[] = configuredSecretValues(),
 82	): string {
 83	  let redacted = value;
 84	  for (const secret of secretValues) {
 85	    redacted = redacted.replaceAll(secret, REDACTED);
 86	  }
 87	  return redacted
 88	    .replace(KEY_VALUE_SECRET, `$1${REDACTED}`)
 89	    .replace(BEARER_TOKEN, `$1${REDACTED}`);
 90	}
