100	function sanitizeValue(value: unknown, context: SanitizationContext, depth: number): TraceValue {
101	  if (depth > MAX_TRACE_DEPTH) return TRUNCATED;
102	  if (value === undefined) return '[UNDEFINED]';
103	  if (value === null || typeof value === 'boolean') return value;
104	  if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
105	  if (typeof value === 'string') return takeText(value, context);
106	  if (typeof value === 'bigint' || typeof value === 'symbol' || typeof value === 'function') {
107	    return takeText(String(value), context);
108	  }
109	
110	  if (context.seen.has(value)) return '[CIRCULAR]';
111	  context.seen.add(value);
112	
113	  if (Array.isArray(value)) {
114	    const items = value.slice(0, MAX_TRACE_ARRAY_ITEMS)
115	      .map((item) => sanitizeValue(item, context, depth + 1));
116	    if (value.length > MAX_TRACE_ARRAY_ITEMS) items.push(TRUNCATED);
117	    return items;
118	  }
119	
120	  if (!isRecord(value)) return takeText(String(value), context);
121	
122	  const entries: { [key: string]: TraceValue } = {};
123	  const objectEntries = Object.entries(value).slice(0, MAX_TRACE_OBJECT_ENTRIES);
124	  for (const [key, entry] of objectEntries) {
125	    entries[key] = SENSITIVE_KEY.test(key)
126	      ? REDACTED
