 75	  const gatewayKey = process.env.AI_GATEWAY_API_KEY?.trim();
 76	  return gatewayKey ? [gatewayKey] : [];
 77	}
 78	
 79	export function redactSensitiveText(
 80	  value: string,
 81	  secretValues: string[] = configuredSecretValues(),
 82	): string {
 83	  let redacted = value;
 84	  for (const secret of secretValues) {
 85	    redacted = redacted.replaceAll(secret, REDACTED);
 86	  }
 87	  return redacted
 88	    .replace(KEY_VALUE_SECRET, `$1${REDACTED}`)
 89	    .replace(BEARER_TOKEN, `$1${REDACTED}`);
 90	}
 91	
 92	function takeText(value: string, context: SanitizationContext): string {
 93	  const redacted = redactSensitiveText(value, context.secretValues);
 94	  const available = Math.min(MAX_TRACE_STRING_LENGTH, context.remainingText);
 95	  if (available <= 0) return TRUNCATED;
 96	  context.remainingText -= Math.min(redacted.length, available);
 97	  return redacted.length > available ? `${redacted.slice(0, available)}${TRUNCATED}` : redacted;
 98	}
 99	
100	function sanitizeValue(value: unknown, context: SanitizationContext, depth: number): TraceValue {
101	  if (depth > MAX_TRACE_DEPTH) return TRUNCATED;
102	  if (value === undefined) return '[UNDEFINED]';
103	  if (value === null || typeof value === 'boolean') return value;
104	  if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
105	  if (typeof value === 'string') return takeText(value, context);
106	  if (typeof value === 'bigint' || typeof value === 'symbol' || typeof value === 'function') {
107	    return takeText(String(value), context);
108	  }
109	
110	  if (context.seen.has(value)) return '[CIRCULAR]';
111	  context.seen.add(value);
112	
113	  if (Array.isArray(value)) {
114	    const items = value.slice(0, MAX_TRACE_ARRAY_ITEMS)
115	      .map((item) => sanitizeValue(item, context, depth + 1));
116	    if (value.length > MAX_TRACE_ARRAY_ITEMS) items.push(TRUNCATED);
117	    return items;
118	  }
119	
120	  if (!isRecord(value)) return takeText(String(value), context);
121	
122	  const entries: { [key: string]: TraceValue } = {};
123	  const objectEntries = Object.entries(value).slice(0, MAX_TRACE_OBJECT_ENTRIES);
124	  for (const [key, entry] of objectEntries) {
125	    entries[key] = SENSITIVE_KEY.test(key)
126	      ? REDACTED
127	      : sanitizeValue(entry, context, depth + 1);
128	  }
129	  if (Object.keys(value).length > MAX_TRACE_OBJECT_ENTRIES) entries.truncated = TRUNCATED;
130	  return entries;
131	}
132	
133	export function sanitizeTraceValue(
134	  value: unknown,
135	  secretValues: string[] = configuredSecretValues(),
136	): TraceValue {
137	  const sanitized = sanitizeValue(value, {
138	    remainingText: MAX_TRACE_TEXT_BUDGET,
139	    seen: new WeakSet<object>(),
140	    secretValues,
141	  }, 0);
142	  const serialized = JSON.stringify(sanitized);
143	  if (Buffer.byteLength(serialized, 'utf8') <= MAX_TRACE_VALUE_BYTES) return sanitized;
144	
145	  return {
146	    truncated: true,
147	    preview: takeText(serialized, {
148	      remainingText: Math.floor(MAX_TRACE_VALUE_BYTES / 4),
149	      seen: new WeakSet<object>(),
150	      secretValues,
151	    }),
152	  };
153	}
154	
155	function makeTraceRecord(
156	  payload: {
157	    state: AgentState;
158	    evaluation: EvaluationResult;
159	    policy: PolicyDecision;
160	  },
161	  date: Date,
162	  runId: string,
163	): TraceRecord {
164	  const secretValues = configuredSecretValues();
165	  return {
166	    schemaVersion: TRACE_SCHEMA_VERSION,
167	    runId,
168	    timestamp: date.toISOString(),
169	    state: sanitizeTraceValue(payload.state, secretValues),
170	    evaluation: {
171	      assessment: sanitizeTraceValue(payload.evaluation.assessment, secretValues),
172	      model: redactSensitiveText(payload.evaluation.model, secretValues),
173	      latencyMs: Number.isFinite(payload.evaluation.latencyMs) ? payload.evaluation.latencyMs : 0,
174	      rawAnswers: sanitizeTraceValue(payload.evaluation.rawAnswers, secretValues),
175	    },
176	    policy: sanitizeTraceValue(payload.policy, secretValues),
177	  };
178	}
179	
180	function isFileExistsError(error: unknown): boolean {
181	  return isRecord(error) && error.code === 'EEXIST';
182	}
183	
184	async function uniqueTracePath(root: string): Promise<{ path: string; runId: string }> {
185	  const traceDir = path.join(root, 'traces');
186	  await mkdir(traceDir, { recursive: true });
187	
188	  for (let attempt = 0; attempt < MAX_TRACE_WRITE_ATTEMPTS; attempt += 1) {
189	    const date = new Date();
190	    const runId = `${date.toISOString().replaceAll(':', '-').replaceAll('.', '-')}-${randomUUID()}`;
191	    const tracePath = path.join(traceDir, `${runId}.jsonl`);
192	    try {
193	      await writeFile(tracePath, '', { flag: 'wx' });
194	      return { path: tracePath, runId };
195	    } catch (error) {
196	      if (isFileExistsError(error)) continue;
197	      throw error;
198	    }
199	  }
200	
201	  throw new Error('Unable to allocate a unique trace path.');
202	}
203	
204	export async function writeTrace(
205	  root: string,
206	  payload: {
207	    state: AgentState;
208	    evaluation: EvaluationResult;
209	    policy: PolicyDecision;
210	  },
211	): Promise<string> {
212	  try {
213	    const trace = await uniqueTracePath(root);
214	    const record = makeTraceRecord(payload, new Date(), trace.runId);
215	    await writeFile(trace.path, `${JSON.stringify(record)}\n`);
216	    return trace.path;
217	  } catch {
218	    throw new TraceWriteError();
219	  }
220	}
221	
222	export async function createOrchestrationTrace(root: string): Promise<{
223	  path: string;
224	  runId: string;
225	}> {
226	  try {
227	    return await uniqueTracePath(root);
228	  } catch {
229	    throw new TraceWriteError();
230	  }
231	}
232	
233	export async function appendOrchestrationTrace(
234	  trace: { path: string; runId: string },
235	  payload: OrchestrationTracePayload,
236	): Promise<void> {
237	  const secretValues = configuredSecretValues();
238	  const record = {
239	    schemaVersion: ORCHESTRATION_TRACE_SCHEMA_VERSION,
240	    runId: trace.runId,
241	    timestamp: new Date().toISOString(),
242	    iteration: payload.iteration,
243	    stateBefore: sanitizeTraceValue(payload.stateBefore, secretValues),
244	    evaluation: {
245	      assessment: sanitizeTraceValue(payload.evaluation.assessment, secretValues),
246	      model: redactSensitiveText(payload.evaluation.model, secretValues),
247	      latencyMs: Number.isFinite(payload.evaluation.latencyMs) ? payload.evaluation.latencyMs : 0,
248	      rawAnswers: sanitizeTraceValue(payload.evaluation.rawAnswers, secretValues),
249	    },
250	    policy: sanitizeTraceValue(payload.policy, secretValues),
251	    proposal: sanitizeTraceValue(payload.proposal, secretValues),
252	    approval: sanitizeTraceValue(payload.approval, secretValues),
253	    toolInput: sanitizeTraceValue(payload.toolInput, secretValues),
254	    toolResult: sanitizeTraceValue(payload.toolResult, secretValues),
255	    ...(payload.workerRequest === undefined
256	      ? {}
257	      : { workerRequest: sanitizeTraceValue(payload.workerRequest, secretValues) }),
258	    stateAfter: sanitizeTraceValue(payload.stateAfter, secretValues),
259	  };
260	
261	  try {
262	    await appendFile(trace.path, `${JSON.stringify(record)}\n`);
263	  } catch {
264	    throw new TraceWriteError();
265	  }
266	}
